\label{lem:coupling}
 Let~$U$ be uniformly distributed on the interval~$(0,1)$ and independent of~$X$. Set~${Q_k(X)=P(Y=k|X)}$ and define the variable 
 \begin{equation}\label{eq:y-representation}
 \widetilde Y = f(X,U)\vcentcolon=\min\left\lbrace k\in \{1,\ldots, K\} \colon\sum_{j=1}^k Q_j(X)>U\right\rbrace.
 \end{equation}
Then~$(\widetilde Y,X)$ and~$(Y,X)$ are identically distributed.

\label{lem:x-ind-y}  
        (i)~The variables~$X$ and~$Y$ are independent if and only if~$Y$ and~$Y'$ are independent.
        (ii)~There exists~$f\colon \mathcal{H}\to \{1,\ldots, K\}$ such that~$Y=f(X)$, if and only if there is a function~$\ell\in\mathcal{L}_Y$ such that~$Y=\ell(Y')$.

\label{rem:frobenius}
    It can be readily verified that
   ~$$
    p_{i,j}-p_{i}p_{j}=\mathrm{Cov}(Q_i(X),Q_j(X)).
   ~$$
    Thus, setting~$Q(X)=(Q_1(X),\ldots, Q_K(X))'$ and defining~$D=\mathrm{diag}(p_{1},\ldots, p_{K})$, we may alternatively write
    \begin{align}
    (K-1)\psi(X,Y)&=\|D^{-1/2}\,\mathrm{Var}(Q(X))\,D^{-1/2}\|_F^2\label{eq:repfrob}\\
    &=\mathrm{vec}(\mathrm{Var}(Q(X)))' \  (D\otimes D)^{-1} \ \mathrm{vec}(\mathrm{Var}(Q(X))).\label{eq:repkron}
    \end{align}
     We will refer later to the alternative representations~\eqref{eq:repfrob} and \eqref{eq:repkron}.

\label{le:suff2}
Let~$\mathcal{V}_k=\{(x,u)\in \mathcal{H}\times (0,1)\colon f(x,u)=k\}$. If we have \begin{equation}
\label{eq:condsuff2}
P\left((X,U)\in \bigcup_{k=1}^K\partial\mathcal{V}_k\right)=0,
\end{equation}
then Assumption~\ref{ass:convergence} holds.

\label{thm:clt}
    Assume that~$X$ and~$Y$ are independent, set
\begin{equation*}
P_n=\sqrt{n}\,\mathrm{vec}\Big(((\widehat p_{k,l} -\widehat p_{k}\widehat{ q_{l}}))_{k,l=1}^{K-1}\Big),
\end{equation*}
     and let ~$\Sigma_n=\mathrm{Var}(P_n|X_1,\ldots,X_n)$.

\noindent     (i) Then under Assumption~\ref{ass:convergence} 
     \begin{align*}
&\Sigma_n((k_1,l_1), (k_2,l_2))\\
&\qquad=p_{k_1}p_{l_1}p_{k_2}p_{l_2}(1+W_{n})\\
        &\qquad\quad- p_{k_1}p_{l_1}p_{l_2}(1\lbrace k_1=k_2\rbrace + W_{n} 1\lbrace l_1=k_2\rbrace)\\
        &\qquad\quad-p_{k_1}p_{l_1}p_{k_2}(1\lbrace l_1=l_2\rbrace + W_{n} 1\lbrace k_1=l_2\rbrace)\\
        &\qquad\quad+p_{k_1}p_{l_1}(1\lbrace k_1=k_2, l_1=l_2\rbrace + W_{n} 1\lbrace k_1=l_2, l_1=k_2\rbrace)+o_P(1), 
     \end{align*}
     with
\begin{equation}\label{eq:W1n}
W_{n}\vcentcolon=\frac{1}{n}\sum_{i=1}^n I\{N(N(i))=i\}.
\end{equation}
(ii) Let Assumption~\ref{ass:neighbour-degree} hold and suppose that we have some~$b>0$ such that
\begin{equation}\label{eq:lambdamin}
P(W_n\leq 1-b)\to 1.
\end{equation}
Then for large enough~$n$ the matrix~$\Sigma_n$ is invertible and
    \begin{equation*}
    \mathcal{I}_n^0\vcentcolon=P_n'\Sigma_n^{-1}P_n \stackrel{\mathcal{D}}{\longrightarrow} \chi^2((K-1)^2),\quad (n\to\infty).
    \end{equation*}
     If~$\widehat \Sigma_n$ denotes the empirical analogue to~$\Sigma_n$ with~$p_k$ replaced by their estimators~$\widehat p_k$, then we also have 
\begin{equation*}
    \mathcal{I}_n\vcentcolon=P_n'\widehat\Sigma_n^{-1}P_n \stackrel{\mathcal{D}}{\longrightarrow} \chi^2((K-1)^2).
    \end{equation*}

To clarify the relationship between~$\mathcal{I}_n$ and~$\widehat\psi(X,Y)$, we refer to the representation of~$\psi(X,Y)$ given in \eqref{eq:repkron}. Observe that~$P_n/\sqrt{n}$ serves as the sample analogue of~$\mathrm{vec}(\mathrm{Var}(Q^{[-K]}(X)))$, where~$Q^{[-K]}(X)$ excludes the redundant component
 \begin{equation*}
     Q_K(X) = 1 - Q_1(X) - \cdots - Q_{K-1}(X)
 \end{equation*}
 from~$Q(X)$. To account for dependencies between the coordinates of~$P_n$ and to obtain a pivotal limit distribution, the weighting matrix of the quadratic form is suitably adjusted.

\label{lem:limitW1n}
    Suppose~$\mathcal{H}=\mathbb{R}^d$ and assume that~$X_i$ have a continuous density. Then we have~$W_{n}\stackrel{\mathcal{P}}{\longrightarrow} \gamma_d\vcentcolon=\frac{\mathrm{vol}(\mathcal{S}_d)}{\mathrm{vol}(\mathcal{S}_d\cup 
    \mathcal{S}_{1,d})}$, where~$\mathcal{S}_d$ is the unit-sphere in~$\mathbb{R}^d$ and~$\mathcal{S}_{1,d}$ is an affine shift of~$\mathcal{S}_d$ by distance 1. It holds that~$\gamma_d\in (1/2, 2/3]$, with~$\gamma_1=2/3$ and~$\gamma_d\searrow  1/2$ for~$d\to\infty$.

\label{cor:consistent-test}
Let Assumptions~\ref{ass:convergence} and~\ref{ass:neighbour-degree} hold. Assume that~$X$ and~$Y$ are not independent. Then
$\mathcal{I}_n\stackrel{\mathcal{P}}{\longrightarrow}\infty$  as~$n\to\infty$. The divergence rate is of order  $\sqrt{n}$.

\label{lem:convergence}
    (i) Under Assumption~\ref{ass:convergence}  it holds for all~${k,l}$ that
    \begin{equation*}
        \widehat p_{k,l}\stackrel{\mathcal{P}}{\longrightarrow} p_{k,l},\quad (n\to\infty).
    \end{equation*}
    \par (ii) If we additionally impose \eqref{ref:assasconv}, then convergence in probability can be strengthened to almost sure convergence.

\label{lem:clt}
    We denote~$\Sigma_{g,n}=\mathrm{Var}(P_n|\mathcal{G}_n=g)$ and let~$\mathcal{K}_n, n\geq 1$, be a sequence of collections of nearest neighbour graphs~$g$ with~$n$ vertices, such that
    \begin{equation*}
        \sup_{g\in \mathcal{K}_n}\mathrm{deg}(g)= o\left(n^{1/4}\right)
    \end{equation*}
    and such that the coefficient~$W_{n}$ defined in \eqref{eq:W1n} and corresponding to~$g$ is at most~${1-b/2}$. Then, for any vector~$c$ on the~$(K-1)^2$-dimensional unit sphere it holds that
    \begin{equation*}
        \sup_{g\in\mathcal K_n}\sup_{z\in\mathbb{R}} \left|P\left(c'\Sigma_{g,n}^{-1/2}P_n\leq z\middle| \mathcal G_n = g\right)-\Phi(z)\right|\to 0,\quad (n\to \infty).
    \end{equation*}

\label{lem:conditional}
Under the assumptions of Theorem~\ref{thm:general-norms} it holds that
\begin{equation*}
    \|\operatorname{Var}(Q(X,Z))\|\geq \|\operatorname{Var}(Q(X))\|,
\end{equation*}
with equality if and only if~$Y$ is independent of $Z$ conditionally on $X$.

\label{lem:convergence-distribution-1}
Suppose Assumption~\ref{ass:convergence} holds. Then for~$n\to\infty$, we have
\begin{equation*}
    (Y_1,Y_{N(1)}, Y_2, Y_{N(2)})\stackrel{\mathcal{D}}{\longrightarrow} (Y_1, Y_1', Y_2, Y_2').
\end{equation*}

\label{lem:combes}
    Let~$\mathcal{X}_1,\ldots, \mathcal{X}_n$ be a collection of arbitrary metric spaces and set~${\mathcal{X}=\mathcal{X}_1\times\ldots\times\mathcal{X}_n}$. Let~$\mathcal{Y}\subset \mathcal{X}$ and let~$X$ be an~$\mathcal{X}$-valued random variable. Denote~${p=P(X\notin \mathcal Y)}$.
    If~$f:\mathcal{X}\to\mathbb{R}$ is such that for all pairs~$x,y\in\mathcal Y$ which are only distinct in the~$i$-th coordinate we have \begin{equation}\label{eq:bounded-differences}
        |f(x)-f(y)|\leq c_i,
    \end{equation}
    then it holds that \begin{equation}\label{eq:combes}
        P(|f(X)-\mathbb{E}\,\left(f(X)|X\in\mathcal Y\right)|\geq \varepsilon)\leq 2p+2\exp\left(-\frac{2\left(\varepsilon-p\sum_{i=1}^n c_i\right))^2}{\sum_{i=1}^n c_i^2}\right).
    \end{equation}

\label{lem:determinant}
    It holds that
    \begin{align*}    \mathrm{det}\left(\Sigma_{n}\right)&=\left(1+W_{n}\right)^{K(K-1)/2}\left(1-W_{n}\right)^{(K-1)(K-2)/2}\prod_{i=1}^{K} p_i^{2(K-1)}.
    \end{align*}

\label{thm:rinott}[\cite{rinott_normal_1994}, Thm. 2.2]
 Let~$V_1,\ldots,V_n$ be random variables having a dependence graph whose maximal degree is strictly less than~$k$ and satisfy
 \begin{enumerate}
 \item~$|V_i|\leq~B$ almost surely for~$i=1,\ldots,n$,
 \item~$\mathbb{E}\,  V_i =0$ and
 \item~$\operatorname{Var}(\sum_{i=1}^n V_i)=1$.
 \end{enumerate}
 Then
 \begin{equation}\label{eq:rinott}
 \left|P\left(\sum_{i=1} V_i\leq~z\right)-\Phi(z)\right|\leq~\sqrt{\frac{1}{2\pi}}kB+16\sqrt{n}k^{3/2}B^2+10nk^2B^3.
 \end{equation}
